steps.script:
# The drawn ring radius must be move-cap px PLUS the model's base extent.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var ring = m.get_node("BoardRoot/MoveRangeVisual")
var radius: float = ring.get_child(0).points[0].distance_to(mc.drag_start_pos)
var cap_px: float = Measurement.inches_to_px(mc.move_cap_inches)
var extent: float = Measurement.base_extent_px(mc.selected_model)
m.set_meta("ring_probe", "radius=%.1f cap_px=%.1f extent=%.1f" % [radius, cap_px, extent])
return abs(radius - (cap_px + extent))

# Regression guard: the pre-fix ring was drawn at exactly the move cap. The
# ring must now sit a whole base extent further out than that.
var mc = tree.root.get_node("Main").movement_controller
var ring = tree.root.get_node("Main").get_node("BoardRoot/MoveRangeVisual")
var radius: float = ring.get_child(0).points[0].distance_to(mc.drag_start_pos)
return radius - Measurement.inches_to_px(mc.move_cap_inches)

# THE FIX. At this legal max-range position the furthest point of the model's
# base must sit ON the ring. Before the fix the ring stopped at the centre's
# reach, so this overhang was a full base extent (~79px) of base sticking out
# past the green dashes.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var ring = m.get_node("BoardRoot/MoveRangeVisual")
var radius: float = ring.get_child(0).points[0].distance_to(mc.drag_start_pos)
var moved: float = mc.current_path[1].distance_to(mc.drag_start_pos)
var extent: float = Measurement.base_extent_px(mc.selected_model)
var overhang: float = (moved + extent) - radius
m.set_meta("overhang_probe", "base_edge_vs_ring=%.2fpx old_ring_overhang=%.2fpx" % [overhang, (moved + extent) - Measurement.inches_to_px(mc.move_cap_inches)])
return abs(overhang)
